// ========================================
// JWT TOKEN VALIDATION & USER AUTHENTICATION
// ========================================
// Validates Supabase JWT and extracts user info

const webhookData = $json;
const headers = webhookData.headers || {};

// Extract JWT token from Authorization header
const authHeader = headers.authorization || headers.Authorization || '';
const token = authHeader.replace(/^Bearer\s+/i, '').trim();

if (!token) {
  throw new Error('UNAUTHORIZED: Missing authorization token. Include: Authorization: Bearer YOUR_JWT_TOKEN');
}

// Decode JWT (base64url decode the payload)
try {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new Error('Invalid JWT format');
  }

  // Decode payload (middle part)
  const payload = JSON.parse(
    Buffer.from(parts[1].replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString()
  );

  // Extract user info
  const userId = payload.sub;
  const userEmail = payload.email;
  const exp = payload.exp;

  if (!userId || !userEmail) {
    throw new Error('Invalid token: missing user information');
  }

  // Check expiration
  const now = Math.floor(Date.now() / 1000);
  if (exp && exp < now) {
    throw new Error('UNAUTHORIZED: Token expired');
  }

  console.log('✅ JWT validated');
  console.log('   User ID:', userId);
  console.log('   Email:', userEmail);

  // Extract request body
  const requestBody = webhookData.body || {};

  return [{
    json: {
      // Auth data
      userId: userId,
      userEmail: userEmail,
      authToken: token,

      // Request metadata
      ipAddress: headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown',
      userAgent: headers['user-agent'] || 'unknown',
      requestTimestamp: new Date().toISOString(),

      // Request body (passed through)
      requestBody: requestBody,

      status: 'authenticated'
    }
  }];

} catch (error) {
  throw new Error('UNAUTHORIZED: Invalid or malformed JWT token - ' + error.message);
}

// ========================================
// VALIDATE INPUT & PREPARE JOB
// ========================================

const authData = $('1️⃣ JWT Validator').item.json;
const userProfile = $json[0]; // Supabase returns array

if (!userProfile) {
  throw new Error('User profile not found');
}

const requestBody = authData.requestBody;

// Generate job ID
const jobId = 'ugc_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);

// Validate binary data (product image)
const binaryData = $binary;
let productImageBinary = null;
let binaryPropertyName = null;

if (binaryData && Object.keys(binaryData).length > 0) {
  binaryPropertyName = Object.keys(binaryData)[0];
  productImageBinary = binaryData[binaryPropertyName];
  console.log('✅ Product image found:', productImageBinary.fileName);
} else {
  throw new Error('No product image uploaded. Please include product image in request.');
}

// Parse UGC Type
const ugcType = requestBody.ugcType || requestBody['UGC Type'] || 'Holding Product - Natural pose';
const ugcTypeMap = {
  'Holding Product - Natural pose': { 
    style: 'natural', setting: 'home', emotion: 'confident',
    sceneStyle: 'casual handheld', cameraAngle: 'eye-level'
  },
  'Using Product - In action': { 
    style: 'action', setting: 'lifestyle', emotion: 'satisfied',
    sceneStyle: 'dynamic usage', cameraAngle: 'slightly above'
  },
  'Unboxing - First impression': { 
    style: 'excited', setting: 'home', emotion: 'surprised',
    sceneStyle: 'close-up unboxing', cameraAngle: 'top-down'
  },
  'Mirror Selfie - Authentic angle': { 
    style: 'casual', setting: 'bedroom', emotion: 'happy',
    sceneStyle: 'mirror reflection', cameraAngle: 'selfie angle'
  },
  'Before & After - Transformation': { 
    style: 'testimonial', setting: 'home', emotion: 'amazed',
    sceneStyle: 'split comparison', cameraAngle: 'direct to camera'
  },
  'Cozy at Home - Relaxed setting': { 
    style: 'cozy', setting: 'living_room', emotion: 'relaxed',
    sceneStyle: 'lifestyle cozy', cameraAngle: 'warm intimate'
  },
  'Friend Sharing - Social moment': { 
    style: 'social', setting: 'cafe', emotion: 'friendly',
    sceneStyle: 'candid social', cameraAngle: 'natural conversation'
  },
  'ASMR': { 
    style: 'asmr', setting: 'quiet', emotion: 'calm',
    sceneStyle: 'close-up detailed', cameraAngle: 'macro focus'
  },
  'Podcast': { 
    style: 'podcast', setting: 'studio', emotion: 'conversational',
    sceneStyle: 'interview setup', cameraAngle: 'medium shot'
  }
};

const ugcConfig = ugcTypeMap[ugcType] || ugcTypeMap['Holding Product - Natural pose'];

// Parse Duration
const durationText = requestBody.duration || requestBody['Duration'] || '16s Problem + Solution';
let duration = 16;
let totalScenes = 2;

if (durationText.includes('24s')) { duration = 24; totalScenes = 3; }
else if (durationText.includes('32s')) { duration = 32; totalScenes = 4; }
else if (durationText.includes('40s')) { duration = 40; totalScenes = 5; }
else if (durationText.includes('48s')) { duration = 48; totalScenes = 6; }
else if (durationText.includes('56s')) { duration = 56; totalScenes = 7; }
else if (durationText.includes('64s')) { duration = 64; totalScenes = 8; }

// Check subscription limits
if (userProfile.subscription_tier === 'free' && duration > 64) {
  throw new Error('FREE_TIER_LIMIT: Free tier limited to 64 seconds. Upgrade to Pro for longer videos.');
}

// Target Audience
const targetAudience = requestBody.targetAudience || requestBody['Target Audience'] || 'Gen Z (18-24)';

// Platform
const platform = requestBody.platform || requestBody['Platform'] || 'TikTok/Reels (9:16)';
let aspectRatio = '9:16';
if (platform.includes('16:9')) aspectRatio = '16:9';
else if (platform.includes('1:1')) aspectRatio = '1:1';

const output = {
  // Job identifiers
  jobId: jobId,
  requestId: jobId,

  // User info
  userId: authData.userId,
  userEmail: authData.userEmail,
  subscriptionTier: userProfile.subscription_tier,
  creditsBalance: userProfile.credits_balance,

  // Product info
  productName: requestBody.productName || requestBody['Product Name'] || 'Product',
  productDescription: requestBody.productDescription || requestBody['Product Description'] || '',

  // UGC Configuration
  ugcType: ugcType,
  ugcConfig: ugcConfig,

  // Video specs
  duration: duration,
  totalScenes: totalScenes,
  sceneDuration: duration === 64 ? 8 : (duration / totalScenes),
  aspectRatio: aspectRatio,
  platform: platform,
  targetAudience: targetAudience,

  // Credits
  creditsCost: 10,

  // Binary info
  productImageFile: {
    fileName: productImageBinary.fileName,
    mimeType: productImageBinary.mimeType,
    fileSize: productImageBinary.fileSize,
    binaryPropertyName: binaryPropertyName
  },

  // Request metadata
  ipAddress: authData.ipAddress,
  userAgent: authData.userAgent,

  // Status
  status: 'validated',
  timestamp: authData.requestTimestamp
};

console.log('✅ Input validated');
console.log('   Job ID:', jobId);
console.log('   User:', authData.userEmail, '(', userProfile.subscription_tier, ')');
console.log('   Credits Balance:', userProfile.credits_balance);

return [{ 
  json: output,
  binary: binaryData 
}];

